import { Download, Upload } from "lucide-react";
import { Button } from "@/components/ui/button";
import { FileTypeIcon } from "@/components/ui/file-type-icon";

/*
  THE DOCUMENTS TABLE — one for every record that keeps files (3PL Delivery
  Orders, the portal's order requests and invoice disputes). The 3PL
  anatomy, which is the source of truth (Pavan, 2026-10-14):

    Document (its format icon, then the name) · Added · By · ↓
    (No Kind column — Pavan, 2026-10-14: the format icon says what it is.)

  ALWAYS A TABLE, AND NEVER EMPTY OF ROWS. With nothing uploaded it still
  holds one row (Pavan, 2026-10-14): where the reader can add, that row IS
  the upload — press it to pick files; where they cannot, it says what will
  arrive. The section never changes shape when the first file lands.
*/

export interface DocumentRow {
  id: string;
  kind: string;
  name: string;
  /** Already formatted for reading. */
  added: string;
  by: string;
}

export function DocumentsTable({
  rows,
  onAdd,
  emptyText = "No documents yet.",
  onDownload,
}: {
  rows: DocumentRow[];
  /** Given, the empty row is an upload slot. */
  onAdd?: () => void;
  /** The empty row's words when there is no upload here. */
  emptyText?: string;
  onDownload?: (row: DocumentRow) => void;
}) {
  return (
    <table className="w-full table-fixed text-sm">
      <colgroup>
        <col />
        <col className="w-[18%]" />
        <col className="w-[20%]" />
        <col className="w-12" />
      </colgroup>
      <thead>
        <tr className="border-b border-border bg-fp-table-header">
          {["Document", "Added", "By"].map((h) => (
            <th key={h} className="px-3 py-2 text-left text-xs font-medium text-muted-foreground">
              {h}
            </th>
          ))}
          <th className="w-10 px-3 py-2" />
        </tr>
      </thead>
      <tbody>
        {rows.length === 0 &&
          (onAdd ? (
            /* THE EMPTY ROW IS THE UPLOAD. */
            <tr className="h-12 cursor-pointer border-b border-border last:border-0 hover:bg-fp-row-hover" onClick={onAdd}>
              <td className="px-3">
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onAdd();
                  }}
                  className="flex items-center gap-2 rounded-sm text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                >
                  <Upload className="size-4" />
                  Upload a document
                </button>
              </td>
              <td className="px-3 text-muted-foreground">—</td>
              <td className="px-3 text-muted-foreground">—</td>
              <td />
            </tr>
          ) : (
            <tr className="h-12">
              <td colSpan={4} className="px-3 text-muted-foreground">
                {emptyText}
              </td>
            </tr>
          ))}
        {rows.map((doc) => (
          <tr key={doc.id} className="h-12 border-b border-border last:border-0">
            <td className="px-3">
              <span className="flex min-w-0 items-center gap-2.5">
                <FileTypeIcon name={doc.name} />
                <span className="truncate text-foreground" title={doc.name}>
                  {doc.name}
                </span>
              </span>
            </td>
            <td className="truncate px-3 text-muted-foreground">{doc.added}</td>
            <td className="truncate px-3 text-muted-foreground">{doc.by}</td>
            <td className="px-2">
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label={`Download ${doc.name}`}
                className="text-muted-foreground"
                onClick={() => onDownload?.(doc)}
              >
                <Download />
              </Button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-all outline-none focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60 dark:focus-visible:ring-destructive/40",
        // `bg-transparent`, NOT `bg-background`. `--background` is the APP
        // background (#efefeb light), which is right only when the button sits
        // ON it — and wrong on the white content layer, where every toolbar and
        // every table row puts outline buttons. Measured on one gallery route
        // before this change: 51 controls filled #efefeb on a #ffffff layer.
        //
        // Transparent is neutral-or-better everywhere, which is why this belongs
        // in the variant rather than at call sites: on the app background it
        // composites to the identical colour, on the content layer it renders
        // #ffffff, and on a card it inherits the card instead of fighting it.
        //
        // The stroke is `--input` in BOTH themes now. The variant already used
        // `--input` in dark; light was the odd one out at `--border` (#cdd4de vs
        // the field's #abb3c2), so an outline button read a shade lighter than
        // the input beside it in every toolbar.
        outline:
          "border border-input bg-transparent hover:bg-accent hover:text-accent-foreground dark:bg-fp-field-fill dark:hover:bg-fp-field-fill-hover",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        // The affirmative counterpart to `destructive`: a filled button for the
        // one action that MOVES SOMETHING FORWARD where an outline would be
        // read as optional. Same green the status family uses, with its own
        // foreground — see the note on `--status-success-foreground`.
        success:
          "bg-status-success text-status-success-foreground hover:bg-status-success/90 focus-visible:ring-status-success/30",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        xs: "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
        "icon-xs": "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot.Root : "button"

  return (
    <Comp
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }

import { cn } from "@/lib/utils";

/*
  FILE TYPE ICON (Pavan, 2026-10-14) — a document outline with its format on
  a tag, beside every uploaded file's name: PDF, PNG, SVG, JPG, DOC, XLS, CSV…
  After his reference (a file with a "PDF" tag on its left edge).

  THE TAG'S COLOUR SAYS THE FAMILY, so a list can be scanned by kind: PDF red
  · images violet · documents blue · spreadsheets green · archives orange ·
  anything else ink. The text on the tag carries the format, so colour is
  never the only cue. Lane tokens — the same in both themes.
*/

const FAMILY: Record<string, string> = {
  pdf: "bg-fp-lane-red",
  png: "bg-fp-lane-violet",
  jpg: "bg-fp-lane-violet",
  jpeg: "bg-fp-lane-violet",
  gif: "bg-fp-lane-violet",
  svg: "bg-fp-lane-violet",
  webp: "bg-fp-lane-violet",
  heic: "bg-fp-lane-violet",
  doc: "bg-fp-lane-blue",
  docx: "bg-fp-lane-blue",
  txt: "bg-fp-lane-blue",
  rtf: "bg-fp-lane-blue",
  xls: "bg-fp-lane-green",
  xlsx: "bg-fp-lane-green",
  csv: "bg-fp-lane-green",
  zip: "bg-fp-lane-orange",
};

/** The file's extension, from its name — "" when it has none. */
export const extensionOf = (name: string) => {
  const m = /\.([a-z0-9]{1,5})$/i.exec(name.trim());
  return m ? m[1].toLowerCase() : "";
};

export function FileTypeIcon({ name, className }: { name: string; className?: string }) {
  const ext = extensionOf(name);
  const label = (ext === "jpeg" ? "jpg" : ext || "file").slice(0, 4).toUpperCase();
  return (
    <span aria-hidden data-slot="file-type-icon" className={cn("relative inline-flex h-7 w-6 shrink-0", className)}>
      {/* THE SHEET — an outline with a folded corner. */}
      <svg viewBox="0 0 24 28" className="size-full text-foreground/70" fill="none">
        <path
          d="M5 1.5h9.5L21.5 8.5V24.5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-21a2 2 0 0 1 2-2Z"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinejoin="round"
        />
        <path d="M14.5 1.5v5a2 2 0 0 0 2 2h5" stroke="currentColor" strokeWidth="1.5" strokeLinejoin="round" />
        <path d="M8 19.5h9M8 22.5h6" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
      </svg>
      {/* THE FORMAT — on a tag over the sheet's left edge. */}
      <span
        className={cn(
          "absolute top-[9px] -left-1 rounded-[3px] px-[3px] py-px text-[7px] leading-none font-bold tracking-wide",
          FAMILY[ext] ? `${FAMILY[ext]} text-white` : "bg-foreground text-background"
        )}
      >
        {label}
      </span>
    </span>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/** Merge conditional class names and de-dupe Tailwind utilities. */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
